    "content": "Genel tanımlar (inşaat, proje, yönetim), inşaat sektörünün özellikleri, inşaat projeleri, inşaat türleri, inşaat sektörü için gerekli olan kaynaklar, proje yaşam döngüsü, inşaat projesi katılımcıları, inşaat yönetiminin önemi. Proje Yönetimi. Proje katılımcılarının organizasyonu. İnşaat maliyetlendirmesi ve ihale süreci. Kamu İhale Mevzuatı. İnşaat Planlaması. İş Programı Teknikleri. İleri iş programı teknikleri. Maliyet Kontrol. Kazanılmış değer analizi.",
