    "name": "İNŞAAT YÖNETİMİNDE TEKNOLOJİ UYGULAMALARI",
    "type": "Seçmeli",
    "credit": 3,
    "ects": 6,
    "theory": 3,
    "practice": 0,
    "term": "Güz",
    "instructor": "Arş.Gör.Dr. MİTAT ÖZTÜRK",
    "purpose": "Bu dersin amacı, inşaat yönetimi süreçlerinde kullanılan güncel teknolojileri tanıtmak ve bu teknolojilerin proje planlama, maliyet kontrolü, kalite yönetimi, iş güvenliği ve sürdürülebilirlik üzerindeki etkilerini analiz etmektir. Öğrencilere, dijital dönüşümün inşaat sektöründeki rolünü kavrama ve teknolojiyi etkin bir şekilde kullanma becerisi kazandırmak hedeflenmektedir.",
    "content": "Ders kapsamında; inşaat yönetiminde bilgi teknolojilerinin kullanımı, yapay zekâ destekli planlama ve karar verme sistemleri, veri analitiği, mobil uygulamalar, dijital proje yönetimi yazılımları ve sürdürülebilir inşaat teknolojileri konuları ele alınmaktadır. Ayrıca güncel örnekler ve vaka analizleri üzerinden teknolojik yeniliklerin yönetim süreçlerine entegrasyonu tartışılmaktadır.",
    "methods": "Kuramsal anlatım, problem çözme, bilimsel kaynak incelemesi ve mühendislik bulgularının tartışılması.",
    "resources": "Dersin gerçek OBS kaynakları; güncel iktisat literatürü, hakemli makaleler ve ilgili ulusal/uluslararası veri kaynakları.",
    "sdgs": [
      "8",
      "9",
      "11"
    ],
    "outcomes": [
      "İnşaat yönetiminde teknoloji uygulamaları kapsamındaki ileri kuramsal bilgileri analiz eder.",
      "Yapım ve proje yönetimi yaklaşımlarını karşılaştırır.",
      "İnşaat yönetiminde teknoloji uygulamaları kapsamında uygun iktisadi modeli uygular.",
      "İnşaat yönetiminde teknoloji uygulamaları bulgularını ekonomik ve toplumsal etkileriyle değerlendirir.",
      "İnşaat yönetiminde teknoloji uygulamaları alanındaki kanıtlara dayalı politika çıkarımları geliştirir."
    ],
