    "content": "Hidrostatik, süreklilik, momentum ve momentumun momenti denklemlerinin kontrol hacmi yaklaşımı ile çıkarılması, Süreklilik ve momentum denklemlerinin diferansiyel yaklaşımla kartezyen, silindirik ve akım çizgisi koordinatlarında çıkarılması, Navier-Stokes denklemleri, türbülanslı akım teorisi.",
