    "type": "Seçmeli",
    "credit": 3,
    "ects": 6,
    "theory": 3,
    "practice": 0,
    "term": "Güz",
    "instructor": "Dr. Öğr. Üyesi GÖKHAN YÜCEL",
    "purpose": "Bu dersin amacı, yapıların deprem etkisi altındaki davranışlarının performans esaslı değerlendirilmesini öğretmektir. Öğrencilere, doğrusal olmayan analiz yöntemleri, plastik mafsal modelleri, performans seviyeleri ve hedef yer değiştirmeye dayalı tasarım yaklaşımları hakkında ileri düzey bilgi kazandırmak hedeflenir. Ayrıca öğrencilerin mevcut yapıların performansını analiz ederek olası güçlendirme stratejileri geliştirme yetkinliği kazanmaları amaçlanır.",
    "content": "Deprem mühendisliğinde performans kavramı; performans hedefleri ve yönetmelik esasları; doğrusal ve doğrusal olmayan analiz yöntemleri; plastik mafsal ve fiber tabanlı modelleme yaklaşımları; itme analizi (pushover) ve zaman tanım alanı analizi yöntemleri; hedef yer değiştirme ve performans değerlendirme kriterleri; TBDY-2018 ve ASCE 41-17 esaslarına göre performans analizleri; güçlendirme stratejileri ve örnek uygulamalar.",
    "methods": "Ders yüz yüze yürütülmektedir. Ders kapsamında anlatım, problem çözümü, soru-cevap, tartışma, örnek olay incelemesi, yönetmelik incelemesi, doğrusal olmayan analiz uygulamaları, performans değerlendirme örnekleri ve proje/rapor çalışmaları kullanılmaktadır.",
    "resources": "Dersin gerçek OBS kaynakları; güncel iktisat literatürü, hakemli makaleler ve ilgili ulusal/uluslararası veri kaynakları.",
    "sdgs": [
      "9",
      "11",
      "13"
    ],
    "outcomes": [
      "Performans esaslı yapı analizi kapsamındaki ileri kuramsal bilgileri analiz eder.",
      "Yapı mühendisliği yaklaşımlarını karşılaştırır.",
      "Performans esaslı yapı analizi kapsamında uygun iktisadi modeli uygular.",
      "Performans esaslı yapı analizi bulgularını ekonomik ve toplumsal etkileriyle değerlendirir.",
      "Performans esaslı yapı analizi alanındaki kanıtlara dayalı politika çıkarımları geliştirir."
    ],
