    "content": "Doğrusal olmayan yapı davranışının nedenleri, çözüm yolları ve stabilite konusu ele alınacaktır",
    "methods": "Temel teorinin hazır bir yazılım olan \"MATLAB\" ile ispatlanması ve açık kaynak kodlu bir program olan \"OpenSees\" kullanılarak uygulanması",
