    "content": "Betonu oluşturan malzemeler, çimentolar, agregalar, agrega türleri, agrega granülümetri optimizasyonu, karışım ve bakim suyu özellikleri, katkı maddeleri kullanımı, beton karışım hesabi, taze beton ve özellikleri, işlenebilirlik ve ölçülmesi. Beton türleri, katılaşmış betonun mekanik özellikleri. Rötre, sünme, dayanım ve bunları etkileyen faktörler. Beton durabilitesi ve etkileyen faktörler. Aşınma, boşluk oranı ve geçirimlilik. Karbonatlaşma, alkali agrega reaksiyonu, donma çözünme ve sülfat atağının betona zararları ve zarar verme mekanizmaları.",
