    "code": "İNŞ820",
    "name": "İNŞAAT MÜHENDİSLİĞİNDE YAPAY ZEKA UYGULAMALAR...",
    "type": "Seçmeli",
    "credit": 3,
    "ects": 6,
    "theory": 3,
    "practice": 0,
    "term": "Bahar",
    "instructor": "Arş.Gör.Dr. MİTAT ÖZTÜRK",
    "purpose": "Bu dersin amacı, inşaat mühendisliği problemlerinin çözümünde yapay zekâ (YZ) ve makine öğrenmesi (MÖ) yöntemlerinin nasıl kullanılabileceğini öğretmektir. Öğrencilere, veri odaklı yaklaşımlar geliştirerek yapı analizi, malzeme özelliklerinin tahmini, proje optimizasyonu, risk analizi ve karar destek sistemleri gibi mühendislik uygulamalarında yapay zekâ tekniklerini kullanabilme becerisi kazandırmak hedeflenmektedir.",
    "content": "Ders kapsamında yapay zekânın temelleri, makine öğrenmesi algoritmaları, yapay sinir ağları, veri ön işleme ve modelleme, optimizasyon teknikleri, uzman sistemler ve karar destek araçları ele alınmaktadır. Ayrıca yapı mühendisliği, geoteknik, ulaştırma, su kaynakları ve inşaat yönetimi alanlarında yapay zekâ uygulamalarına ilişkin örnek çalışmalar ve vaka analizleri incelenmektedir.",
    "methods": "Kuramsal anlatım, problem çözme, bilimsel kaynak incelemesi ve mühendislik bulgularının tartışılması.",
    "resources": "Dersin gerçek OBS kaynakları; güncel iktisat literatürü, hakemli makaleler ve ilgili ulusal/uluslararası veri kaynakları.",
