    "instructor": "Dr. Öğr. Üyesi İBRAHİM KARATAŞ",
    "purpose": "Dersin amacı; inşaat sektöründe teknolojinin artan etkisiyle ortaya çıkan Yapı Bilgi Modellemesi (YBM) sürecinin anlatılması, bu süreçte kullanılan programların uygulanması ve öğrencilerin Yapı Bilgi Modellemesi sistemini uygulamak için temel beceriler kazanmasıdır.",
    "content": "Yapı bilgi modellemesinin (YBM) incelenmesi, avantajları ve dezavantajlarının belirlenmesi, Türkiye'de ve Dünya'da YBM kullanımı, LOD kavramının incelenmesi, YBM sürecinin modellenmesi için gerekli programların uygulanması ve bu programlar ile neler yapılacağının anlatılması.",
    "methods": "Yapı Bilgi Modelleme tabanlı bilgisayar programlarından biri kullanılarak programın tanıtımı ve ara yüzü, Komutlara erişim, Proje, dosya oluşturulması ve kullanılması, Temel modüller: Çizim komutları, Nesne düzeltme ve değiştirme komutları, Nokta yakalama ve görüntü kontrol komutları, Eleman modifikasyonu, Katman oluşturulması ve kullanımı, Kütüphane oluşturulması ve kullanımı, Tarama, Eleman biçim özelliklerinin kullanımı, Yazı, Ölçülendirme ayarları ve ölçülendirmenin yapılması, Farklı türde dosya alınması ve transferi, Mimari Modül: Yapı strüktürü oluşturma, duvar, kolon, kiriş, döşeme, çatı, merdiven, temel, kapı, pencere, baca, gibi yapı elemanlarının üç boyutlu akıllı modellenmesi.",
    "resources": "Dersin gerçek OBS kaynakları; güncel iktisat literatürü, hakemli makaleler ve ilgili ulusal/uluslararası veri kaynakları.",
