    "term": "Bahar",
    "instructor": "Doç. Dr. TARIK BARAN",
    "purpose": "Depreme dayanıklı yapı tasarımı ilkelerini, ve onarım ve güçlendirme ilkelerini öğretmek ve deprem yönetmeliklerini tanıtmak.",
    "content": "Depremler: Yer Hareketinin Özellikleri ve Deprem Parametreleri, Basit Yapıların Deprem Hesabı, Elastik ve Hesap Spektrumlarının Hesabı ve Kullanılışı, Eşdeger Statik Yöntem, Modal Spektral Hesap, Deprem Yönetmelikleri, Sünek Yapı Tasarımı ve Önemi, Betonarme, Çelik ve Prefabrike Yapıların Sünek Tasarımı Esasları, Depreme Dayanıklı Yapı Tasarımında Diger Pasif ve Aktif Yöntemler, Yapılarda Deprem Hasarları, Mevcut ve Hasarlı Yapıların Tamir ve Güçlendirilmesi.",
    "methods": "Yüz yüze",
    "resources": "Dersin gerçek OBS kaynakları; güncel iktisat literatürü, hakemli makaleler ve ilgili ulusal/uluslararası veri kaynakları.",
    "sdgs": [
      "9",
      "11",
      "13"
    ],
    "outcomes": [
      "Depreme dayanıklı yapı tasarımı kapsamındaki ileri kuramsal bilgileri analiz eder.",
      "Yapı mühendisliği yaklaşımlarını karşılaştırır.",
      "Depreme dayanıklı yapı tasarımı kapsamında uygun iktisadi modeli uygular.",
      "Depreme dayanıklı yapı tasarımı bulgularını ekonomik ve toplumsal etkileriyle değerlendirir.",
      "Depreme dayanıklı yapı tasarımı alanındaki kanıtlara dayalı politika çıkarımları geliştirir."
    ],
