    "term": "Bahar",
    "instructor": "Doç. Dr. BEHCET DÜNDAR",
    "purpose": "Yapı malzemelerinin özelliklerini ve bu özelliklerin iç yapı ile ilişkilerini tanıtmak; malzeme ile ilgili standartları, yasa ve yönetmelikleri tanıtmak, buna uygun malzeme üretiminin koşullarını ve üretim yöntemini açıklamak, farklı ortam koşullarında oluşacak hasar türlerini ve hasar oranlarını tanıtmak, kusurları malzemenin fiziksel ve kimyasal özelliklerine bağlı olarak açıklamak.",
    "content": "İyi bir betonda aranılan özellikler ve katkı malzemelerinin tanımı ve kullanım nedenleri. Beton için katkı malzemesi kullanımında göz önüne alınması ve dikkat edilmesi gereken hususlar. Katkı malzemelerinin sınıflandırılması. Hava katkı malzemeleri. Su azaltıcı katkı malzemeleri. Beton prizini hızlandırıcı ve geciktirici katkı malzemeleri. Puzolanlar ve diğer ince öğütülmüş mineral katkı malzemeleri. Doğal puzolanlar. Uçucu küller. Silica dumanı. Yüksek fırın cürufları. Diğer bazı katkı malzemeleri.",
